using Payments;

namespace PaymentGateway.Tests;

[TestClass]
public sealed class PaymentGatewayTests
{
    private readonly Payments.PaymentGateway _gateway;

    public PaymentGatewayTests()
    {
        _gateway = new Payments.PaymentGateway();
    }

    #region ChargeAsync Tests

    [TestMethod]
    public async Task ChargeAsync_ValidCardAndAmount_ReturnsSuccessResult()
    {
        // Arrange
        var cardToken = "tok_visa_valid";
        var amount = 50.00m;

        // Act
        var result = await _gateway.ChargeAsync(cardToken, amount);

        // Assert
        Assert.IsNotNull(result);
        Assert.IsTrue(result.Success);
        Assert.IsNotNull(result.ChargeId);
    }

    [TestMethod]
    public async Task ChargeAsync_ValidCharge_ReturnsNonEmptyChargeId()
    {
        // Arrange
        var cardToken = "tok_visa_valid";
        var amount = 25.99m;

        // Act
        var result = await _gateway.ChargeAsync(cardToken, amount);

        // Assert
        Assert.IsNotNull(result.ChargeId);
        Assert.AreNotEqual(string.Empty, result.ChargeId);
    }

    [TestMethod]
    [DataRow("")]
    [DataRow(null)]
    public async Task ChargeAsync_NullOrEmptyCardToken_ThrowsArgumentException(string? cardToken)
    {
        // Act & Assert
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(cardToken!, 10.00m));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    [DataRow(-100.50)]
    public async Task ChargeAsync_ZeroOrNegativeAmount_ThrowsArgumentException(double amount)
    {
        // Act & Assert
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync("tok_valid", (decimal)amount));
    }

    [TestMethod]
    public async Task ChargeAsync_DeclinedCard_ReturnsFailureResult()
    {
        // Arrange
        var cardToken = "tok_declined";
        var amount = 100.00m;

        // Act
        var result = await _gateway.ChargeAsync(cardToken, amount);

        // Assert
        Assert.IsNotNull(result);
        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    [DataRow(0.01, DisplayName = "Minimum charge")]
    [DataRow(9999.99, DisplayName = "Large charge")]
    [DataRow(49.95, DisplayName = "Typical charge")]
    public async Task ChargeAsync_VariousValidAmounts_ReturnsSuccess(double amount)
    {
        // Act
        var result = await _gateway.ChargeAsync("tok_visa_valid", (decimal)amount);

        // Assert
        Assert.IsTrue(result.Success);
    }

    #endregion

    #region RefundAsync Tests

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccessResult()
    {
        // Arrange
        var chargeId = "ch_valid_123";

        // Act
        var result = await _gateway.RefundAsync(chargeId);

        // Assert
        Assert.IsNotNull(result);
        Assert.IsTrue(result.Success);
        Assert.IsNotNull(result.RefundId);
    }

    [TestMethod]
    public async Task RefundAsync_ValidRefund_ReturnsNonEmptyRefundId()
    {
        // Arrange
        var chargeId = "ch_valid_456";

        // Act
        var result = await _gateway.RefundAsync(chargeId);

        // Assert
        Assert.IsNotNull(result.RefundId);
        Assert.AreNotEqual(string.Empty, result.RefundId);
    }

    [TestMethod]
    [DataRow("")]
    [DataRow(null)]
    public async Task RefundAsync_NullOrEmptyChargeId_ThrowsArgumentException(string? chargeId)
    {
        // Act & Assert
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(chargeId!));
    }

    [TestMethod]
    public async Task RefundAsync_NonExistentChargeId_ReturnsFailureResult()
    {
        // Arrange
        var chargeId = "ch_nonexistent_999";

        // Act
        var result = await _gateway.RefundAsync(chargeId);

        // Assert
        Assert.IsNotNull(result);
        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public async Task RefundAsync_AlreadyRefundedCharge_ReturnsFailure()
    {
        // Arrange
        var chargeId = "ch_already_refunded";

        // Act
        var result = await _gateway.RefundAsync(chargeId);

        // Assert
        Assert.IsFalse(result.Success);
    }

    #endregion

    #region Integration / Round-trip Tests

    [TestMethod]
    public async Task ChargeAndRefund_FullRoundTrip_BothSucceed()
    {
        // Arrange & Act - Charge
        var chargeResult = await _gateway.ChargeAsync("tok_visa_valid", 75.00m);
        Assert.IsTrue(chargeResult.Success);

        // Act - Refund the charge
        var refundResult = await _gateway.RefundAsync(chargeResult.ChargeId);

        // Assert
        Assert.IsTrue(refundResult.Success);
        Assert.IsNotNull(refundResult.RefundId);
    }

    #endregion
}

